using Astrea.BattleActions;

namespace Astrea;

public class WhereXTimesCustomDescription : CustomBattleActionDescription
{
	protected string GetActionDescription(string amountModified, BattleAction battleAction, BattleAction purifyCorruptAction)
	{
		string firstArgument = purifyCorruptAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)).RemoveLast();
		return base.localizationManager.GetLocalizedWhereXTimes(firstArgument, amountModified == "-1", GetRawLocalizedDescription(battleAction));
	}
}
